test('Held review locks overlapping controls and actual source CAS conflict preserves decision draft',async({page})=>{
 await ready(page);const response=await submit(page);await changeRole(page,'reviewer');await selected(page,response.snapshot.id);let release,entered=false,settled=false;const held=new Promise(resolve=>{release=resolve;pendingRelease=resolve;});const handler=async route=>{entered=true;await held;const result=await route.fetch();await route.fulfill({response:result});settled=true;};await page.route('**/api/cms/reviews',handler);await page.locator('#site-review-outcome').selectOption('CHANGES_REQUESTED');await page.locator('#site-review-note').fill('Synthetic source CAS decision');await page.locator('#site-review-submit').click();await expect.poll(()=>entered).toBe(true);for(const id of ['site-snapshot-load','site-snapshot-submit','site-source-load','site-source-submit','site-review-submit'])await expect(page.locator('#'+id)).toBeDisabled();
 await api(page,'/api/cms/source-checks',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':randomUUID()},body:JSON.stringify({snapshotId:response.snapshot.id,contentHash:response.snapshot.contentHash,expectedReviewRevision:0,expectedSourceRevision:0,checks:[{claimPath:'creative-copy',evidence:[{sourceId:'baseline-source'}]}]})});const before=await collectionState(db);release();await expect.poll(()=>settled).toBe(true);await expect(page.locator('#site-review-status')).not.toContainText('Đang lưu');await expect(page.locator('#site-review-note')).toHaveValue('Synthetic source CAS decision');expect(await collectionState(db)).toEqual(before);const current=await api(page,'/api/cms/snapshots/'+response.snapshot.id);expect(current.review).toBeNull();expect(current.reviewState.sourceRevision).toBe(1);await page.unroute('**/api/cms/reviews',handler);details.conflict={sourceVersusReviewCAS:true,allPendingControlsLocked:true,fullDocumentDigestNoReviewWrite:true};
});

test('Coherent wrong Snapshot follow GET cannot acknowledge captured saved content or replace unknown Submit intent',async({page})=>{
 await ready(page);const attempts=[];let actualId,wrongResponse,wrongRead=false,settled=0;const post=async route=>{const request=route.request();attempts.push({key:request.headers()['idempotency-key'],body:request.postData()});const response=await route.fetch();expect(response.status()).toBe(201);const receipt=await response.json();actualId=receipt.id;if(attempts.length===1){wrongResponse=structuredClone(await api(page,'/api/cms/snapshots/'+actualId));wrongResponse.snapshot.content.hero.note='Synthetic coherent wrong Snapshot content';const contentHash=sha({content:wrongResponse.snapshot.content,mediaManifestHash:wrongResponse.snapshot.mediaManifestHash,schemaVersion:2,templateVersion:'m2-site-baseline-v1'});wrongResponse.snapshot.contentHash=contentHash;wrongResponse.summary.contentHash=contentHash;await page.route('**/api/cms/snapshots/'+actualId,async get=>{if(!wrongRead){wrongRead=true;await get.fulfill({status:200,contentType:'application/json',body:JSON.stringify(wrongResponse)});}else await get.continue();});await route.fulfill({status:201,contentType:'application/json',body:JSON.stringify(wrongResponse.summary)});}else await route.fulfill({response});settled++;};await page.route('**/api/cms/snapshots',post);await page.locator('#site-snapshot-submit').click();await expect.poll(()=>settled).toBe(1);await expect.poll(()=>wrongRead).toBe(true);await expect(page.locator('#site-submit-status')).not.toContainText('Đang gửi');await expect(page.locator('#site-snapshot-summary')).toBeEmpty();await expect(page.locator('#site-submit-message')).toBeDisabled();await expect(page.locator('#site-source-submit')).toBeDisabled();await page.locator('#site-snapshot-submit').click();await expect.poll(()=>settled).toBe(2);expect(attempts[1]).toEqual(attempts[0]);await expect(page.locator('#site-snapshot-summary')).toContainText(actualId);expect((await api(page,'/api/cms/snapshots/'+actualId)).snapshot.content).toEqual(original.content);details.submitBinding={coherentWrongContentRejected:true,originalIntentReplayConfirmed:true};
});

